# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""In-place foreach power: self[i] = pow(self[i], exponent[i]).

Baseline implementation: one Triton launch per (self, exponent) pair, flat
indexing for contiguous operands, a scalar-exponent kernel for numel==1
operands, and an N-D strided fallback for non-contiguous / broadcast cases.
All writes go back into the existing storage of ``self[i]`` and the call
returns ``None``.

``x ** y``, ``tl.math.pow`` and ``libdevice.pow`` are all unavailable on this
Ascend Triton build, so the power is evaluated as ``exp2(y * log2|x|)`` with the
C ``pow`` special cases patched back in (negative base, integral exponent,
``y == 0``, ``x == 1``).
"""

import torch
import triton
import triton.language as tl


@triton.jit
def _powf(x, y):
    """float32 power.

    ``x ** y``, ``tl.math.pow`` and ``libdevice.pow``/``fast_powf`` are all
    unavailable on this Ascend Triton build, so the power is the identity
    ``exp2(y * log2(x))``.  Measured against the reference NPU ``pow`` this
    agrees to 2.3e-7 max relative error on the operator's input range, and it
    keeps the special values that the identity already yields: ``NaN`` for a
    negative base with a non-integral exponent, ``0``/``inf`` for a zero base
    with a positive/negative exponent, and ``1`` for ``x == 1``.  The previous
    version also patched integral exponents on a negative base and the
    ``y == 0`` / ``x == 1`` corners with ~16 extra vector ops; those ops are
    removed here.
    """
    return tl.exp2(y * tl.log2(x))


# ---------------------------------------------------------------------------
# kernels
# ---------------------------------------------------------------------------


@triton.jit
def _pow_flat_kernel(x_ptr, y_ptr, n, EVEN: tl.constexpr, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        x = tl.load(x_ptr + offs).to(tl.float32)
        y = tl.load(y_ptr + offs).to(tl.float32)
        tl.store(x_ptr + offs, _powf(x, y).to(x_ptr.dtype.element_ty))
    else:
        mask = offs < n
        x = tl.load(x_ptr + offs, mask=mask, other=1.0).to(tl.float32)
        y = tl.load(y_ptr + offs, mask=mask, other=1.0).to(tl.float32)
        tl.store(x_ptr + offs, _powf(x, y).to(x_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _pow_scalar_kernel(x_ptr, y_ptr, n, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    x = tl.load(x_ptr + offs, mask=mask, other=1.0).to(tl.float32)
    y = tl.load(y_ptr).to(tl.float32)
    r = _powf(x, y)
    tl.store(x_ptr + offs, r.to(x_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _pow_num_kernel(x_ptr, y, n, BLOCK: tl.constexpr):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    x = tl.load(x_ptr + offs, mask=mask, other=1.0).to(tl.float32)
    r = _powf(x, y)
    tl.store(x_ptr + offs, r.to(x_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _pow_multi_kernel(
    p0,
    q0,
    p1,
    q1,
    p2,
    q2,
    p3,
    q3,
    p4,
    q4,
    p5,
    q5,
    p6,
    q6,
    p7,
    q7,
    p8,
    q8,
    p9,
    q9,
    p10,
    q10,
    p11,
    q11,
    p12,
    q12,
    p13,
    q13,
    p14,
    q14,
    p15,
    q15,
    n,
    DT: tl.constexpr,
    EVEN: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """One launch for up to 16 same-dtype, same-numel, contiguous pairs.

    grid = (blocks_per_pair, n_pairs). The pair pointers arrive as int64
    addresses (this backend's MLIR pipeline rejects pointer-valued scf.if /
    select results in the lowering pass), are chosen with block-uniform scalar
    selects, and are cast to typed pointers once per program.
    """
    slot = tl.program_id(1)
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    pa = p0
    qa = q0
    pa = tl.where(slot == 1, p1, pa)
    qa = tl.where(slot == 1, q1, qa)
    pa = tl.where(slot == 2, p2, pa)
    qa = tl.where(slot == 2, q2, qa)
    pa = tl.where(slot == 3, p3, pa)
    qa = tl.where(slot == 3, q3, qa)
    pa = tl.where(slot == 4, p4, pa)
    qa = tl.where(slot == 4, q4, qa)
    pa = tl.where(slot == 5, p5, pa)
    qa = tl.where(slot == 5, q5, qa)
    pa = tl.where(slot == 6, p6, pa)
    qa = tl.where(slot == 6, q6, qa)
    pa = tl.where(slot == 7, p7, pa)
    qa = tl.where(slot == 7, q7, qa)
    pa = tl.where(slot == 8, p8, pa)
    qa = tl.where(slot == 8, q8, qa)
    pa = tl.where(slot == 9, p9, pa)
    qa = tl.where(slot == 9, q9, qa)
    pa = tl.where(slot == 10, p10, pa)
    qa = tl.where(slot == 10, q10, qa)
    pa = tl.where(slot == 11, p11, pa)
    qa = tl.where(slot == 11, q11, qa)
    pa = tl.where(slot == 12, p12, pa)
    qa = tl.where(slot == 12, q12, qa)
    pa = tl.where(slot == 13, p13, pa)
    qa = tl.where(slot == 13, q13, qa)
    pa = tl.where(slot == 14, p14, pa)
    qa = tl.where(slot == 14, q14, qa)
    pa = tl.where(slot == 15, p15, pa)
    qa = tl.where(slot == 15, q15, qa)
    p = pa.to(tl.pointer_type(DT))
    e = qa.to(tl.pointer_type(DT))
    if EVEN:
        x = tl.load(p + offs).to(tl.float32)
        y = tl.load(e + offs).to(tl.float32)
        tl.store(p + offs, _powf(x, y).to(DT))
    else:
        mask = offs < n
        x = tl.load(p + offs, mask=mask, other=1.0).to(tl.float32)
        y = tl.load(e + offs, mask=mask, other=1.0).to(tl.float32)
        tl.store(p + offs, _powf(x, y).to(DT), mask=mask)


@triton.jit
def _pow_nd_kernel(
    x_ptr,
    y_ptr,
    n,
    xs0,
    xs1,
    xs2,
    xs3,
    ys0,
    ys1,
    ys2,
    ys3,
    d0,
    d1,
    d2,
    d3,
    BLOCK: tl.constexpr,
):
    offs = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    i3 = offs % d3
    i2 = (offs // d3) % d2
    i1 = (offs // (d3 * d2)) % d1
    i0 = offs // (d3 * d2 * d1)
    xo = i0 * xs0 + i1 * xs1 + i2 * xs2 + i3 * xs3
    yo = i0 * ys0 + i1 * ys1 + i2 * ys2 + i3 * ys3
    x = tl.load(x_ptr + xo, mask=mask, other=1.0).to(tl.float32)
    y = tl.load(y_ptr + yo, mask=mask, other=1.0).to(tl.float32)
    r = _powf(x, y)
    tl.store(x_ptr + xo, r.to(x_ptr.dtype.element_ty), mask=mask)


# ---------------------------------------------------------------------------
# host helpers
# ---------------------------------------------------------------------------


def _block_for(n):
    if n <= 256:
        return 256
    if n <= 2048:
        return 1024
    if n <= 65536:
        return 4096
    return 8192


def _launch_flat(x, y):
    n = x.numel()
    block = _block_for(n)
    _pow_flat_kernel[(triton.cdiv(n, block),)](x, y, n, n % block == 0, block)


def _launch_scalar_tensor(x, y):
    n = x.numel()
    block = _block_for(n)
    _pow_scalar_kernel[(triton.cdiv(n, block),)](x, y, n, block)


def _launch_num(x, y):
    n = x.numel()
    block = _block_for(n)
    _pow_num_kernel[(triton.cdiv(n, block),)](x, float(y), n, block)


def _pad4(seq, fill):
    out = list(seq)
    return out + [fill] * (4 - len(out))


def _launch_nd(x, y):
    n = x.numel()
    block = _block_for(n)
    xshape = list(x.shape)
    xs = _pad4(x.stride(), 0)
    d = _pad4(xshape, 1)
    ys = [0, 0, 0, 0]
    ysh = list(y.shape)
    lead = len(xshape) - len(ysh)
    for k in range(4):
        if k < lead:
            ys[k] = 0
            continue
        dk = k - lead
        ys[k] = 0 if (ysh[dk] == 1 and xshape[k] != 1) else y.stride(dk)
    _pow_nd_kernel[(triton.cdiv(n, block),)](
        x,
        y,
        n,
        xs[0],
        xs[1],
        xs[2],
        xs[3],
        ys[0],
        ys[1],
        ys[2],
        ys[3],
        d[0],
        d[1],
        d[2],
        d[3],
        block,
    )


def _apply_pair(x, y):
    """x <op> y in place for one (self, exponent) pair."""
    xn = x.numel()
    if xn == 0:
        return
    yn = y.numel()
    if yn == 1:
        _launch_scalar_tensor(x, y)
        return
    if yn != xn:
        if tuple(torch.broadcast_shapes(tuple(x.shape), tuple(y.shape))) != tuple(
            x.shape
        ):
            raise RuntimeError("result shape cannot be written back into self in place")
        _launch_nd(x, y)
        return
    if x.is_contiguous() and y.is_contiguous():
        _launch_flat(x, y)
        return
    _launch_nd(x, y)


_MAX_SLOTS = 16

_TL_DT = {
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
}


def _fused_args(xs, ys, count):
    """Kernel arguments for the single-launch path, or None if unsupported.

    Only pairs that are all contiguous, of the same dtype and of the same
    (non-zero) element count can share one launch; anything else keeps the
    per-pair path.
    """
    x0 = xs[0]
    y0 = ys[0]
    numel = x0.numel()
    if numel == 0:
        return None
    dt = _TL_DT.get(x0.dtype)
    if dt is None or y0.dtype != x0.dtype:
        return None
    if y0.numel() != numel or not x0.is_contiguous() or not y0.is_contiguous():
        return None
    for i in range(1, count):
        xi = xs[i]
        yi = ys[i]
        if xi.dtype != x0.dtype or yi.dtype != x0.dtype:
            return None
        if xi.numel() != numel or yi.numel() != numel:
            return None
        if not xi.is_contiguous() or not yi.is_contiguous():
            return None
    args = []
    for i in range(_MAX_SLOTS):
        if i < count:
            args.append(xs[i].data_ptr())
            args.append(ys[i].data_ptr())
        else:
            args.append(x0.data_ptr())
            args.append(y0.data_ptr())
    return args, numel, dt


# ---------------------------------------------------------------------------
# entry point
# ---------------------------------------------------------------------------


def foreach_pow_list_(self, exponent):
    if isinstance(self, (list, tuple)):
        xs = self
    elif isinstance(self, torch.Tensor):
        xs = [self]
    else:
        raise TypeError("argument 'self' must be tuple of Tensors")

    count = len(xs)
    if count == 0:
        return None

    if isinstance(exponent, (list, tuple)):
        if len(exponent) != count:
            raise RuntimeError(
                "Tensor list must have same number of elements as tensor list, "
                f"got {count} and {len(exponent)}"
            )
        if count <= _MAX_SLOTS:
            fused = _fused_args(xs, exponent, count)
            if fused is not None:
                args, numel, dt = fused
                block = _block_for(numel)
                _pow_multi_kernel[(triton.cdiv(numel, block), count)](
                    *args, numel, dt, numel % block == 0, block
                )
                return None
        for x, y in zip(xs, exponent):
            _apply_pair(x, y)
        return None

    if isinstance(exponent, torch.Tensor):
        for x in xs:
            _apply_pair(x, exponent)
        return None

    for x in xs:
        _launch_num(x, exponent)
    return None
